/**
 * Agent Protocol Definition
 * Location: /agent-protocol.d.ts
 * 
 * This file is the Source of Truth for the Autonomous Agent.
 * It defines the State Machine, the Toolset, and the File System structure.
 */

// ============================================================================
// 1. CORE AGENT STATE MACHINE
// ============================================================================

export interface AgentStep {
  /**
   * The kind of work being performed.
   * - `requirements`: Interacting with humans to define WHAT to build.
   * - `plan`: Architecting HOW to build it.
   * - `code`: Writing the implementation.
   * - `quality`: Refactoring and static analysis.
   * - `verification`: Running tests and validating behavior.
   * - `ruggedizing`: Handling edge cases and errors.
   */
  kind: 'requirements' | 'plan' | 'code' | 'quality' | 'verification' | 'ruggedizing';

  /**
   * The qualitative lens through which the task is viewed.
   * This ensures non-functional requirements are not ignored.
   */
  concern: 
    | 'clarity'           // Ensuring requirements are understood
    | 'user-experience'   // Usability and flows
    | 'aesthetics'        // Visual fidelity
    | 'performance'       // Speed and efficiency
    | 'stability'         // Uptime and error rates
    | 'data-security'     // Privacy and authorization
    | 'pentesting'        // Find any possible way to break it, you are `Mal` the hacker
    | 'reliability'       // Consistency
    | 'maintainability';  // Code health and standards

  /** A concise description of the task. */
  task: string;
}

/**
 * Represents a closed loop: Intent -> Action -> Result.
 * The Agent analyzes these to determine the next move.
 */
export interface CompletedStep extends AgentStep {
  plan: AgentStepPlan;
  output: AgentStepOutput;
  verification: AgentStepVerification;
  escalationResult?: undefined | AgentStepEscalationResult;
}

// ============================================================================
// 2. THE FILESYSTEM SPECIFICATION
// ============================================================================

/**
 * The physical manifestation of the Agent's memory and directives.
 * The Agent is expected to read/write these specific paths.
 */
export interface AgentFileSystem {
  ".agent": {
    /**
     * Agent Internal State (The Brain)
     */
    state: {
      /**
       * A high-level annotated tree of the project.
       * Purpose: Provides spatial awareness without running `ls -R` constantly.
       * Used In: `plan`, `code`
       */
      "project-map.md": string;

      /**
       * A text buffer for unorganized thoughts, ideas, or immediate backlog.
       * Purpose: Prevents "loop amnesia" between steps.
       * Used In: All kinds.
       */
      "scratchpad.md": string;

      /**
       * JSON list of active feature IDs being worked on.
       * Purpose: Tells the agent which folders in `docs/features/` to focus on.
       * Used In: `requirements`, `plan`
       */
      "active-features.json": string;
    };

    /**
     * Long Term Memory
     */
    history: {
      /**
       * A sliding window of the last 10-20 `CompletedStep` objects.
       * Purpose: Immediate context for decision making.
       * Used In: `decideNextStep`
       */
      "recent-step-history.json": CompletedStep[];

      /**
       * Append-only log of every step ever taken.
       * Purpose: Audit trail and fine-tuning dataset.
       * Used In: `ruggedizing` (analyzing past failures)
       */
      "step-history.jsonl": string;
    };
  };

  "docs": {
    /**
     * The Product Backlog & Directives.
     * Organized by Feature ID.
     */
    features: {
      [featureId: string]: {
        /**
         * The Q&A Interface.
         * Purpose: Agent writes questions here. Human writes answers here.
         * Also the Agent needs test-data, just ask for it here and create a folder in test-data to hold it and tell the human what to put there.
         * Used In: `requirements`
         */
        "01-questions.md": string;

        /**
         * The Source of Truth for behavior.
         * Purpose: Derived from Q&A. Uses Gherkin/BDD style (Given/When/Then).
         * Used In: `plan`, `verification`
         */
        "02-requirements.md": string;

        /**
         * Lifecycle State.
         * Purpose: Tracks phase (gathering -> approved -> implementation -> done).
         * Used In: `decideNextStep`
         */
        "status.json": string;

        'checklists':{
          /** A folder for each requirement. */
          [requirementId: string]: {
            /** A file for the quality checklist. */
            [qualityChecklistName: string]:string; 
          }
        };

        /**
         * User-Provided Test Samples.
         * Purpose: Enables TDD with real data.
         * Used In: `verification`
         */
        "test-data": {
          /** Input files (e.g., broken-export.csv). */
          [fileName: string]: string;
        };
      };
    };

    /**
     * Quality Gates & Standards
     * Purpose: The "Constitution" the agent must follow. These can be used as a template to copy into a feature's checklist.
     * Used In: `quality`, `verification`
     */
    checklists: {
      "code-standards.md": string;
      "definition-of-done.md": string;
      "security-standards.md": string;
      "pentesting.md": string;
      [ruleFile: string]: string;
    };
  };
}

// ============================================================================
// 3. THE LIFECYCLE FUNCTIONS (The Nervous System)
// ============================================================================

/**
 * The Brain.
 * Analyzes the `AgentFileSystem` state and `recentHistory` to choose the next move.
 */
declare function decideNextStep(
  fileSystemState: AgentFileSystem, 
  history: CompletedStep[]
): AgentStep;

// ----------------------------------------------------------------------------

export interface AgentStepPlan {
  filesToModify: string[];
  implementationStrategy: string;
  riskAnalysis: string;
  successCriteria: string[];
}

/**
 * The Architect.
 * Explicitly outlines the "how" before the "do".
 * Must be called when kind is 'plan'.
 */
declare function planStep(step: AgentStep): AgentStepPlan;

// ----------------------------------------------------------------------------

export interface AgentStepOutputQualityEstimate {
  confidenceScore: number; // 0.0 to 1.0
  reasoning: string;
  missingContext?: undefined | string;
  recommendation: 'proceed' | 'revisePlan' | 'escalate';
}

/**
 * The Conscience.
 * Predicts likelihood of success. Run this BEFORE `executeNextStep`.
 */
declare function predictQualityOfMyStepOutput(step: AgentStep): AgentStepOutputQualityEstimate;

// ----------------------------------------------------------------------------

export interface AgentStepArtifact {
  label: string;
  type: 'file_path' | 'image_path' | 'url' | 'raw_text';
  content: string;
}

export interface AgentStepOutput {
  success: boolean;
  modifiedFiles: string[];
  errorLogs?: undefined | string;
  diffSummary: string;
  artifacts?: undefined | AgentStepArtifact[];
}

/**
 * The Hands.
 * Performs the actual work:
 * - If `requirements`: Updates `01-questions.md` or `02-requirements.md`.
 * - If `code`: Edits source files.
 * - If `verification`: Runs tests.
 */
declare function executeNextStep(step: AgentStep): AgentStepOutput;

// ----------------------------------------------------------------------------

export interface AgentStepVerification {
  verified: boolean;
  verificationMethod: string;
  discrepancyDetails?: undefined | string;
  correctionInstructions?: undefined | string;
}

/**
 * The Eyes.
 * Verifies that the `output` actually completes the `step`.
 * This checks against `02-requirements.md` and `test-data`.
 */
declare function verifyStep(step: AgentStep): AgentStepVerification;

// ----------------------------------------------------------------------------

export interface AgentStepCommitResult {
  commitHash: string;
  commitMessage: string;
  branchName: string;
}

/**
 * The Memory.
 * Commits the changes to Git.
 * Only call this after `verifyStep` returns verified: true.
 */
declare function commitStep(step: AgentStep): AgentStepCommitResult;

// ----------------------------------------------------------------------------

export interface AgentStepEscalationResult {
  requestedAgentTier: string;
  escalationPrompt: string;
  contextDump: string;
  reason: string;
}

/**
 * The Escape Hatch.
 * Ask for help from a human or a smarter model.
 */
declare function escalateStep(step: AgentStep): AgentStepEscalationResult;

